const makeSlug = (text: string) =>
  text
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");

const createBrincadeira = (item: Omit<BrincadeiraFamilia, "slug" | "videoUrl">): BrincadeiraFamilia => ({
  ...item,
  slug: makeSlug(item.title),
  videoUrl: videoUrls[item.id - 1],
});

